builder.Services.AddProblemDetails(options =>
{
    options.CustomizeProblemDetails = context =>
    {
        var http = context.HttpContext;
        var correlationId = http.Request.Headers["X-Correlation-ID"].FirstOrDefault()
            ?? http.TraceIdentifier;

        context.ProblemDetails.Extensions["correlationId"] = correlationId;
        context.ProblemDetails.Instance = http.Request.Path;

        if (!http.Response.HasStarted && context.ProblemDetails.Status is >= 500)
            context.ProblemDetails.Detail = null; // hide internals in prod
    };
});

